// Lock Target: marks the enemy the drone locked onto, on every narration sentence after the AI calls lock_target.
// A later lock_target call in the same turn replaces this one, because Stack Calls is off. The lock ends with the turn.

// 1. Read the target. args.name is what the AI passed to lock_target, such as "Rustjaw" or "the growling beast".
//    Drop a leading "the", "a" or "an", since the narration may write the name without it.
const targetName = String(args.name).trim().replace(/^(the|a|an)\s+/i, '');

if (targetName) {
  // 2. List the words to search for: the whole name first, then its last word alone. The AI often shortens a
  //    target as the scene goes on, so "growling beast" later reads as "beast" and "Ser Halden" as "Halden".
  //    A last word under three letters, such as "of" in "Lord of Ash", would mark too much, so it is skipped.
  const lastWord = targetName.split(/\s+/).pop();
  const searchWords = lastWord.length >= 3 && lastWord !== targetName ? [targetName, lastWord] : [targetName];

  // 3. Build one search for those words. Escape the characters a pattern treats as special, so each word
  //    matches as plain text. Match whole words, in any letter case, and take in any bold marks already around
  //    a match, so a name the AI wrote in bold is not marked twice.
  const escapedWords = searchWords.map((word) => word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  const namePattern = new RegExp('\\*{0,2}\\b(?:' + escapedWords.join('|') + ')\\b\\*{0,2}', 'gi');

  // 4. Mark each mention with the drone's reticle, in bold. The mark keeps the narration's own spelling.
  narration.sentence = narration.sentence.replace(namePattern, (mention) => {
    const plainMention = mention.replace(/\*/g, '');
    return '**⌖ ' + plainMention + '**';
  });
}
